/**
 * Worker entry: Astro handles every HTTP request; the scheduled() handler runs
 * the cron jobs (wrangler.jsonc → triggers.crons).
 */
import { handle } from '@astrojs/cloudflare/handler';
import { jobForCron, runJobs } from './lib/jobs';

// `Env` (bindings + secret names) is generated by `npm run cf:types` → worker-configuration.d.ts.
export default {
  fetch: handle,
  async scheduled(controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    const which = jobForCron(controller.cron);
    ctx.waitUntil(
      runJobs(which, { supabaseUrl: import.meta.env.PUBLIC_SUPABASE_URL, secretKey: env.SUPABASE_SERVICE_ROLE_KEY })
        .then((r) => console.log(`cron ${which}`, JSON.stringify(r)))
        .catch((e) => console.error(`cron ${which} failed`, e instanceof Error ? e.message : e)),
    );
  },
} satisfies ExportedHandler<Env>;
